templates.template:
.anchor {
    position: relative;
    top: -50px;
}

.conversationsearchplus-container {
	padding: 20px;
	background: @xf-paletteNeutral1;
	border: 1px solid xf-diminish(@xf-borderColor, 6%);
}

.conversationsearchplus-message-block {
	border-top: 1px solid @xf-borderColorFaint;
	border-bottom: 1px solid @xf-borderColorFaint;
	padding: 20px 0px 20px 0px;
}
